function extractToken(req) {
    const authHeader = req.headers['authorization'] ||'';
    if (authHeader.startsWith('Bearer ')) return authHeader.slice(7).trim();
    return req.headers['x-auth-token'] ||'';
}
const PUBLIC_API_PATHS = new Set(['/api/auth/login','/api/auth/login/verify-otp','/api/auth/webauthn/login-options','/api/auth/webauthn/login-verify','/api/admin/request-password-reset','/api/admin/confirm-password-reset','/api/admin/forgot-password/status','/api/admin/forgot-password/request-otp','/api/admin/forgot-password/confirm','/api/health','/api/relay/license-state']);
app.use(async (req, res, next) => {
    if (!req.path.startsWith('/api/')) return next();
    if (PUBLIC_API_PATHS.has(req.path)) return next();
    // FIX: first-install activation happens BEFORE any user can log in, so it must not require a session token
    // (otherwise the Activate page always failed with "Kailangan mag-login muna. Walang session token.").
    // It is public ONLY while the device is not activated; once activated, replacing the credential needs an Admin login.
    if (req.path === '/api/relay/activate' || req.path === '/api/relay/activation-inbox') {
        // Public habang hindi pa activated, O kapag kumpirmado ng RELAY na expired/revoked ang license (renewal). RELAY pa rin ang nagve-verify ng key.
        if (!isClientActivated() || await checkRenewalNeeded()) return next();
    }
    if (req.path.startsWith('/api/system/reset/status/')) return next();
    const token = extractToken(req);
    if (!token) {
        return res.status(401).json({ success: false, code:'NO_TOKEN', message:'Kailangan mag-login muna. Walang session token.' });
    }
    const session = getSession(token);
    if (!session) {
        return res.status(401).json({ success: false, code:'INVALID_TOKEN', message:'Expired o invalid na ang session. Mangyaring mag-login muli.' });
    }
    const currentDeviceData = readFeatureUnlocks();
    if (currentDeviceData.relayAuthorized === false) {
        destroySession(token);
        return res.status(401).json({
            success: false,
            code:'DEVICE_REVOKED',
            message:'Inalis ng developer/store owner ang device na ito sa listahan ng mga pinapayagang device. Awtomatikong na-logout ka. Kontakin ang developer/store owner.'
        });
    }
    if (Date.now() - lastLiveRecheckAt > DEVICE_REVOCATION_RECHECK_MS) {
        lastLiveRecheckAt = Date.now();
        recheckDeviceAuthorizationLive();
    }
    if (session.mustChangePassword && !roleMustChangeDefaultPassword(session.role)) {
        // Session created before the Admin-only rule: drop the stale flag so it can never block a Cashier/Staff session.
        delete session.mustChangePassword;
        persistSessions();
    }
    if (session.mustChangePassword && roleMustChangeDefaultPassword(session.role) && !PASSWORD_CHANGE_ALLOWED_PATHS.has(req.path)) {
        return res.status(403).json({
            success: false,
            code: 'PASSWORD_CHANGE_REQUIRED',
            message: 'This account still uses a default password. Please set a new password before continuing.'
        });
    }
    req.authUser = { username: session.username, role: session.role };
    req.authToken = token;
    if (req.body && typeof req.body ==='object') {
        // SECURITY FIX: dati, "typeof ... ==='string'" muna bago i-overwrite —
        // kaya kung magpadala ang client ng hindi-string na value para dito
        // (hal. isang array na ["ibang_username"]), hindi ito naa-overwrite
        // dito, pero kapag ginamit bilang object key/property sa ibang
        // endpoint (tulad ng nangyari dati sa /api/cart), awtomatikong
        // pinapabalik ito ni JavaScript sa string ("ibang_username") —
        // type-confusion bypass ng pagpi-pin na ito. Ngayon, basta
        // present ang field, palaging pinapalitan ito papuntang totoong
        // session identity anuman ang type na ipinasa.
        if ('username' in req.body) req.body.username = req.authUser.username;
        if ('user' in req.body) req.body.user = req.authUser.username;
        if ('requester' in req.body) req.body.requester = req.authUser.username;
    }
    if (req.query && typeof req.query ==='object') {
        if ('requester' in req.query) req.query.requester = req.authUser.username;
    }
    next();
});
