    const stored = getStoreSettingsPublic(readData(FILE_STORE_SETTINGS, DEFAULT_STORE_SETTINGS), { ignoreVatLock: true });
    incoming.taxEnabled = false;
    incoming.taxLabel = stored.taxLabel;
