            const g = (t.items || []).reduce((sum, it) => sum + (parseFloat(it.price) || 0) * (parseFloat(it.quantity) || 0), 0);
            if (g <= 0) return null;
            const d = (parseFloat(t.discount) || 0) + (t.items || []).reduce((s, it) => s + (parseFloat(it.itemDiscount) || 0), 0);
            return (d / g) * 100;
