        cloudBackupStatus.lastErrorWasRateLimited = false;
        cloudBackupStatus.lastTotalRecords = totalRecords;
        cloudBackupStatus.lastReusedSegments = reusedCount;
        cloudBackupStatus.lastReusedBytes = reusedRaw;
