const AI_ASSISTANT_MAX_FILE_BYTES = 8 * 1024 * 1024;
const AI_ASSISTANT_MAX_EXTRACTED_CHARS = 20000;
async function extractTextFromAttachedDocument(fileDataUrl, fileName) {
    const raw = fileDataUrl || '';
    const commaIdx = raw.indexOf(',');
    if (!raw.startsWith('data:') || commaIdx === -1) {
        return { success: false, message: 'Invalid file data.' };
    }
    const header = raw.slice(5, commaIdx);
    const base64Payload = raw.slice(commaIdx + 1);
    if (!/;base64$/i.test(header)) {
        return { success: false, message: 'Invalid file data (expected base64-encoded data URL).' };
    }
    const mime = (header.split(';')[0] || '').trim().toLowerCase();
    if (base64Payload.length > AI_ASSISTANT_MAX_FILE_BYTES * 1.4) {
        return { success: false, message: 'That file is too large. Please attach a smaller document (max ~8MB).' };
    }
    let buf;
    try {
        buf = Buffer.from(base64Payload, 'base64');
    } catch (err) {
        return { success: false, message: 'Could not decode the attached file.' };
    }
    if (!buf.length) {
        return { success: false, message: 'The attached file appears to be empty.' };
    }
    if (buf.length > AI_ASSISTANT_MAX_FILE_BYTES) {
        return { success: false, message: 'That file is too large. Please attach a smaller document (max ~8MB).' };
    }
    const lowerName = (fileName || '').toLowerCase();
    try {
        if (mime === 'application/pdf' || lowerName.endsWith('.pdf')) {
            let pdfParse;
            try { pdfParse = require('pdf-parse'); } catch (e) {
                return { success: false, message: 'PDF reading is not enabled on this server yet. Ask your developer to run `npm install pdf-parse`.' };
            }
            const data = await pdfParse(buf);
            return { success: true, text: (data.text || '').trim().slice(0, AI_ASSISTANT_MAX_EXTRACTED_CHARS) };
        }
        if (mime.includes('officedocument.wordprocessingml') || lowerName.endsWith('.docx')) {
            let mammoth;
            try { mammoth = require('mammoth'); } catch (e) {
                return { success: false, message: 'Word document reading is not enabled on this server yet. Ask your developer to run `npm install mammoth`.' };
            }
            const result = await mammoth.extractRawText({ buffer: buf });
            return { success: true, text: (result.value || '').trim().slice(0, AI_ASSISTANT_MAX_EXTRACTED_CHARS) };
        }
        if (mime.startsWith('text/') || /\.(txt|csv|log|md)$/i.test(lowerName)) {
            return { success: true, text: buf.toString('utf8').trim().slice(0, AI_ASSISTANT_MAX_EXTRACTED_CHARS) };
        }
        return { success: false, message: 'Unsupported file type. Supported documents: PDF, DOCX, TXT, CSV.' };
    } catch (err) {
        return { success: false, message: `Could not read the attached file (${err && err.message ? err.message : 'unknown error'}).` };
    }
}
function buildDiagnosticSystemMessage(diagnostics, clientErrors) {
    const parts = [];
    if (diagnostics && typeof diagnostics === 'object') {
        const safe = {
            currentView: typeof diagnostics.currentView === 'string' ? diagnostics.currentView.slice(0, 60) : undefined,
            appVersion: typeof diagnostics.appVersion === 'string' ? diagnostics.appVersion.slice(0, 40) : undefined,
            userAgent: typeof diagnostics.userAgent === 'string' ? diagnostics.userAgent.slice(0, 200) : undefined,
            online: typeof diagnostics.online === 'boolean' ? diagnostics.online : undefined,
            viewport: typeof diagnostics.viewport === 'string' ? diagnostics.viewport.slice(0, 30) : undefined,
            localTime: typeof diagnostics.localTime === 'string' ? diagnostics.localTime.slice(0, 40) : undefined
        };
        parts.push(`Client diagnostic snapshot: ${JSON.stringify(safe)}`);
    }
    if (Array.isArray(clientErrors) && clientErrors.length) {
        const errText = clientErrors.slice(0, 5).map((e) => String(e).slice(0, 300)).join('\n');
        parts.push(`Recent JavaScript errors captured in the user's browser (for troubleshooting/explanation only — do not assume root cause beyond what is shown):\n${errText}`);
    }
    if (!parts.length) return null;
    return {
        role: 'system',
        content: `${parts.join('\n\n')}\n\nIf this diagnostic data is relevant to the question, use it to explain the likely cause in plain language and suggest a safe next step (e.g. reload the page, check internet connection, contact the developer). Never claim you fixed anything yourself — you can only explain and guide.`
    };
}
app.get('/api/ai-assistant/usage', requireAiAssistantOrFree(), async (req, res) => {
    if (!RELAY_API_KEY) return res.status(503).json({ success: false, message: 'RELAY_API_KEY is not configured on this server.' });
    try {
        const installationId = getOrCreateInstallationId(readFeatureUnlocks());
        const relayRes = await relayFetch(`${RELAY_URL}/relay/ai-assistant/usage?installationId=${encodeURIComponent(installationId)}`, { method: 'GET', headers: { 'x-relay-key': RELAY_API_KEY } }, 10000);
        const data = await relayRes.json().catch(() => null);
        if (!relayRes.ok || !data) return res.status(relayRes.status || 502).json(data || { success: false, message: 'AI credit relay request failed.' });
        return res.json(data);
    } catch (err) {
        return res.status(502).json({ success: false, message: err.message || 'Could not get the AI credit status from RELAY.' });
    }
});
