        const specColumns = parsed.rawHeaders
            .map(h => { const m = h.match(/^specs?\s*[:\-]\s*(\S.*)$/i); return m ? { header: h.toLowerCase(), key: m[1].trim().slice(0, 60) } : null; })
            .filter(Boolean);
