            const subDirs = fs.readdirSync(extractDir, { withFileTypes: true }).filter(e => e.isDirectory() && e.name !== '__MACOSX');
            const wrapped = subDirs.find(d => fs.existsSync(path.join(extractDir, d.name, 'server.js')));
