function applyDebtPayment(debt, paymentAmount, recordedBy, meta = {}) {
    if (!Array.isArray(debt.paymentHistory)) debt.paymentHistory = [];
    debt.amountPaid = Math.min(debt.amount, (debt.amountPaid || 0) + paymentAmount);
    debt.paymentHistory.push({
        amount: paymentAmount,
        date: new Date().toISOString(),
        recordedBy,
        method: meta.method || 'manual',
        reference: meta.reference || null
    });
    if (debt.amountPaid >= debt.amount) {
        debt.status = 'paid';
        debt.paidAt = new Date().toISOString();
        awardLoyaltyPointsForPaidDebt(debt, recordedBy);
    } else {
        debt.status = 'partial';
    }
}
const ONLINE_PAYMENT_SWEEP_INTERVAL_MS = 60 * 1000;
let sweepPendingOnlinePaymentsRunning = false;
async function sweepPendingOnlinePayments() {
    if (!getPaymongoSecretKey() && !getXenditSecretKey()) return;
    // RACE FIX: (1) hindi na nagsasapawan ang dalawang sweep (ang network retrieve ay pwedeng tumagal nang higit sa 60s),
    // (2) hindi na isinusulat pabalik ang LUMANG listahan ng debts pagkatapos ng mga await. Dati: binasa ang buong debts,
    // naghintay sa gateway (segundo), saka isinulat ang buong listahan — kaya nabubura ang utang na kakadagdag lang ng
    // C-Credit sale o ang bayad na kakarekord lang ng cashier sa pagitan. Ngayon: ang mga resulta lang ng gateway ang
    // inaalala habang naghihintay, tapos binabasa ulit ang pinakabagong debts at doon inilalapat (walang await sa pagitan).
    if (sweepPendingOnlinePaymentsRunning) return;
    sweepPendingOnlinePaymentsRunning = true;
    try {
        const snapshot = readData(FILE_DEBTS, []);
        const outcomes = [];
        for (const debt of snapshot) {
            const pending = debt.onlinePayment;
            if (!pending || pending.status !== 'pending') continue;
            if (pending.expiresAt && new Date(pending.expiresAt).getTime() < Date.now()) {
                outcomes.push({ debtId: debt.id, intentId: pending.paymentIntentId, kind: 'expired' });
                continue;
            }
            const driver = GATEWAY_DRIVERS[pending.provider] || GATEWAY_DRIVERS.paymongo;
            try {
                const intent = await driver.retrieve(pending.paymentIntentId);
                if (intent.status === 'succeeded') {
                    outcomes.push({ debtId: debt.id, intentId: pending.paymentIntentId, kind: 'succeeded' });
                } else if (intent.status && !['awaiting_payment_method', 'awaiting_next_action', 'processing', 'requires_action', 'accepting_payments', 'pending'].includes(intent.status)) {
                    outcomes.push({ debtId: debt.id, intentId: pending.paymentIntentId, kind: 'status', status: intent.status });
                }
            } catch (e) {                                                                       }
        }
        if (!outcomes.length) return;
        const debts = readData(FILE_DEBTS, []);
        let changed = false;
        for (const outcome of outcomes) {
            const debt = debts.find(d => d.id === outcome.debtId);
            const pending = debt && debt.onlinePayment;
            // Lumipas na ang sitwasyon (nabura ang utang / may bagong QR / naproseso na ng ibang request)? Laktawan.
            if (!pending || pending.status !== 'pending' || pending.paymentIntentId !== outcome.intentId) continue;
            if (outcome.kind === 'expired') {
                pending.status = 'expired';
                changed = true;
            } else if (outcome.kind === 'succeeded') {
                const already = (debt.paymentHistory || []).some(p => p.reference === pending.paymentIntentId);
                if (!already) {
                    applyDebtPayment(debt, pending.amount, 'online-qrph', { method: 'online_qrph', reference: pending.paymentIntentId });
                    logAction('system', `Automatically recorded the QR Ph payment from ${debt.customerName}: ₱${pending.amount.toFixed(2)} (${pending.paymentIntentId} via ${ONLINE_PAYMENT_GATEWAYS[pending.provider] ? ONLINE_PAYMENT_GATEWAYS[pending.provider].name : pending.provider})`);
                }
                pending.status = 'succeeded';
                changed = true;
            } else {
                pending.status = outcome.status;
                changed = true;
            }
        }
        if (changed) writeData(FILE_DEBTS, debts);
    } catch (e) {
        console.error('sweepPendingOnlinePayments error:', e.message);
    } finally {
        sweepPendingOnlinePaymentsRunning = false;
    }
}
setInterval(sweepPendingOnlinePayments, ONLINE_PAYMENT_SWEEP_INTERVAL_MS);
app.post('/api/debts/:id/qrph', requirePermission('customers'), requireFeature('customer_crm'), rateLimit('debt-qrph-create', 20, 15 * 60 * 1000), async (req, res) => {
    try {
        const settings = readData(FILE_ONLINE_PAYMENTS_SETTINGS, DEFAULT_ONLINE_PAYMENTS_SETTINGS);
        if (!settings.qrphEnabled) {
            return res.status(400).json({ success: false, message: 'Online Payments (QR Ph) is disabled. Enable it first in the Online Payments settings.' });
        }
        const selectedProvider = settings.provider === 'xendit' ? 'xendit' : 'paymongo';
        const fallbackAllowed = selectedProvider !== 'paymongo' && settings.fallbackToPaymongoEnabled !== false;
        if (!GATEWAY_DRIVERS[selectedProvider].isConfigured() && !(fallbackAllowed && GATEWAY_DRIVERS.paymongo.isConfigured())) {
            const err = selectedProvider === 'xendit' ? xenditNotConfiguredError() : paymongoNotConfiguredError();
            return res.status(400).json({ success: false, message: err.message });
        }
        const debts = readData(FILE_DEBTS, []);
        const idx = debts.findIndex(d => d.id === req.params.id);
        if (idx === -1) return res.status(404).json({ success: false, message: 'Debt record not found.' });
        const debt = debts[idx];
        const remaining = Math.max(0, debt.amount - (debt.amountPaid || 0));
        if (remaining <= 0) return res.status(400).json({ success: false, message: 'This debt has already been paid.' });
        let amountPHP = parseFloat(req.body.amount);
        if (!amountPHP || amountPHP <= 0) amountPHP = remaining;
        if (amountPHP > remaining + 0.01) {
            return res.status(400).json({ success: false, message: `The amount (₱${amountPHP.toFixed(2)}) exceeds the remaining balance (₱${remaining.toFixed(2)}).` });
        }
        if (amountPHP < 1) {
            return res.status(400).json({ success: false, message: `Minimum amount for QR Ph is ₱1.` });
        }
        const description = `Debt payment - ${debt.customerName} (${debt.id})`;
        let usedProvider = selectedProvider;
        let result;
        try {
            if (!GATEWAY_DRIVERS[selectedProvider].isConfigured()) throw new Error(`${ONLINE_PAYMENT_GATEWAYS[selectedProvider].name} is not configured.`);
            result = await GATEWAY_DRIVERS[selectedProvider].create({ amountPHP, description });
        } catch (primaryErr) {
            if (fallbackAllowed && GATEWAY_DRIVERS.paymongo.isConfigured()) {
                usedProvider = 'paymongo';
                logAction('system', `Falling back to PayMongo for a Debtors QR Ph request (${ONLINE_PAYMENT_GATEWAYS[selectedProvider].name} unavailable: ${primaryErr.message}).`);
                result = await GATEWAY_DRIVERS.paymongo.create({ amountPHP, description });
            } else {
                throw primaryErr;
            }
        }
        // RACE FIX: may await (gateway create) sa itaas — basahin ulit ang pinakabagong debts bago isulat,
        // para hindi mabura ang mga pagbabago (bagong utang/bayad) na nangyari habang naghihintay.
        const debtsAfterGateway = readData(FILE_DEBTS, []);
        const debtAfterGateway = debtsAfterGateway.find(d => d.id === req.params.id);
        if (!debtAfterGateway) {
            throw new Error('Debt record not found (it was removed while the QR Ph request was being created).');
        }
        debtAfterGateway.onlinePayment = {
            provider: usedProvider,
            paymentIntentId: result.id,
            amount: amountPHP,
            status: 'pending',
            createdAt: new Date().toISOString(),
            expiresAt: result.expiresAt
        };
        writeData(FILE_DEBTS, debtsAfterGateway);
        logAction(req.authUser.username, `Created a QR Ph payment request for ${debtAfterGateway.customerName}: ₱${amountPHP.toFixed(2)} (${ONLINE_PAYMENT_GATEWAYS[usedProvider].name})`);
        res.json({ success: true, qrCodeImageUrl: result.qrCodeImageUrl, expiresAt: result.expiresAt, paymentIntentId: result.id, amount: amountPHP, provider: usedProvider });
    } catch (err) {
        res.status(400).json({ success: false, message: err.message || 'Failed to create the QR Ph payment request.' });
    }
});
app.get('/api/debts/:id/qrph/status', requirePermission('customers'), requireFeature('customer_crm'), async (req, res) => {
    try {
        const debts = readData(FILE_DEBTS, []);
        const idx = debts.findIndex(d => d.id === req.params.id);
        if (idx === -1) return res.status(404).json({ success: false, message: 'Debt record not found.' });
        const debt = debts[idx];
        const pending = debt.onlinePayment;
        if (!pending || pending.status !== 'pending') {
            return res.json({ success: true, status: pending ? pending.status : 'none', debt });
        }
        if (pending.expiresAt && new Date(pending.expiresAt).getTime() < Date.now()) {
            pending.status = 'expired';
            writeData(FILE_DEBTS, debts);
            return res.json({ success: true, status: 'expired', debt });
        }
        const driver = GATEWAY_DRIVERS[pending.provider] || GATEWAY_DRIVERS.paymongo;
        const intent = await driver.retrieve(pending.paymentIntentId);
        if (intent.status === 'succeeded') {
            // RACE FIX: may await (gateway retrieve) sa itaas — ilapat sa pinakabagong debts, hindi sa lumang kopya.
            const debtsAfterGateway = readData(FILE_DEBTS, []);
            const debtAfterGateway = debtsAfterGateway.find(d => d.id === req.params.id);
            if (!debtAfterGateway) return res.status(404).json({ success: false, message: 'Debt record not found.' });
            const pendingAfterGateway = debtAfterGateway.onlinePayment;
            if (pendingAfterGateway && pendingAfterGateway.paymentIntentId === pending.paymentIntentId && pendingAfterGateway.status === 'pending') {
                const already = (debtAfterGateway.paymentHistory || []).some(p => p.reference === pendingAfterGateway.paymentIntentId);
                if (!already) {
                    applyDebtPayment(debtAfterGateway, pendingAfterGateway.amount, 'online-qrph', { method: 'online_qrph', reference: pendingAfterGateway.paymentIntentId });
                    logAction('system', `Automatically recorded the QR Ph payment from ${debtAfterGateway.customerName}: ₱${pendingAfterGateway.amount.toFixed(2)} (${pendingAfterGateway.paymentIntentId})`);
                }
                pendingAfterGateway.status = 'succeeded';
                writeData(FILE_DEBTS, debtsAfterGateway);
            }
            return res.json({ success: true, status: 'succeeded', debt: debtAfterGateway });
        }
        return res.json({ success: true, status: intent.status || 'pending', debt });
    } catch (err) {
        res.status(400).json({ success: false, message: err.message || 'Failed to check the QR Ph status.' });
    }
});
function awardLoyaltyPointsForPaidDebt(debt, actorUsername) {
    if (!debt || debt.pointsAwarded || !debt.transactionId) return;
    const storeSettings = getStoreSettingsPublic(readData(FILE_STORE_SETTINGS, DEFAULT_STORE_SETTINGS));
    if (!storeSettings.loyaltyEnabled) return;
    const linkedTx = getRowById(FILE_TRANSACTIONS, debt.transactionId);
    if (!linkedTx || !linkedTx.customerId) return;
    const customers = readData(FILE_CUSTOMERS, []);
    const cust = customers.find(c => c.id === linkedTx.customerId);
    if (!cust) return;
    const earnRate = parseFloat(storeSettings.loyaltyEarnRate) || 100;
    const earned = earnRate > 0 ? Math.floor((parseFloat(debt.amount) || 0) / earnRate) : 0;
    debt.pointsAwarded = true;
    if (earned <= 0) return;
    cust.points = (cust.points || 0) + earned;
    writeData(FILE_CUSTOMERS, customers);
    debt.loyaltyPointsEarned = earned;
    logAction(actorUsername || 'system', `Nag-earn ng ${earned} loyalty points si ${cust.name} matapos ma-fully paid ang C-Credit debt (₱${(parseFloat(debt.amount) || 0).toFixed(2)}, Debt ID: ${debt.id}).`);
}
app.get('/api/debts', requirePermission('customers'), requireFeature('customer_crm'), (req, res) => {
    res.json(readData(FILE_DEBTS, []));
});
app.post('/api/debts', requirePermission('customers'), requireFeature('customer_crm'), (req, res) => {
    const { customerName, phone, amount, note, dueAt, items, transactionId } = req.body;
    if (!customerName || !customerName.trim()) {
        return res.status(400).json({ success: false, message:'Debtor name is required.' });
    }
    const parsedAmount = parseFloat(amount);
    if (!parsedAmount || parsedAmount <= 0) {
        return res.status(400).json({ success: false, message:'A valid amount owed is required.' });
    }
    let dueAtIso = null;
    if (dueAt) {
        const parsedDue = new Date(dueAt);
        if (isNaN(parsedDue.getTime())) {
            return res.status(400).json({ success: false, message:'The due date/time is not valid.' });
        }
        dueAtIso = parsedDue.toISOString();
    }
    const debts = readData(FILE_DEBTS, []);
    if (transactionId && debts.some(d => d.transactionId === String(transactionId))) {
        return res.status(400).json({
            success: false,
            message: 'May existing na debt record na naka-link na sa Transaction ID na ito. Hindi pwedeng mag-link ng dalawang debt sa iisang transaksyon.'
        });
    }
    const debt = {
        id:'DEBT-' + Date.now() +'-' + crypto.randomBytes(3).toString('hex'),
        customerName: customerName.trim(),
        phone: phone ||'',
        amount: parsedAmount,
        amountPaid: 0,
        paymentHistory: [],
        note: note ||'',
        items: Array.isArray(items)
            ? items.map(it => ({
                code: (it && it.code) || '',
                name: (it && it.name) || '',
                quantity: parseInt(it && it.quantity, 10) || 0,
                price: parseFloat(it && it.price) || 0
            })).filter(it => it.name)
            : [],
        transactionId: transactionId ? String(transactionId) : null,
        borrowedAt: new Date().toISOString(),
        dueAt: dueAtIso,
        status:'unpaid',
        createdBy: req.authUser.username,
        createdAt: new Date().toISOString(),
        paidAt: null
    };
    debts.unshift(debt);
    writeData(FILE_DEBTS, debts);
    logAction(req.authUser.username, `Added a new debt record: ${debt.customerName} — ₱${debt.amount.toFixed(2)}`);
    res.json({ success: true, debt });
});
app.put('/api/debts/:id', requirePermission('customers'), requireFeature('customer_crm'), debtAmountEditLimiter, async (req, res) => {
    const body = req.body || {};
    const { customerName, phone, amount, note, dueAt } = body;
    const isAdminUser = String((req.authUser && req.authUser.role) || '').toLowerCase() === 'admin';
    let amountAuthorizer = null;
    let parsedNewAmount = null;
    if (amount !== undefined) {
        parsedNewAmount = parseFloat(amount);
        if (!parsedNewAmount || parsedNewAmount <= 0) {
            return res.status(400).json({ success: false, message:'A valid amount is required.' });
        }
        const currentDebt = readData(FILE_DEBTS, []).find(d => d.id === req.params.id);
        if (!currentDebt) return res.status(404).json({ success: false, message:'Debt record not found.' });
        const amountChanged = Math.abs(parsedNewAmount - (parseFloat(currentDebt.amount) || 0)) >= 0.005;
        if (amountChanged && !isAdminUser) {
            const adminPassword = typeof body.adminPassword === 'string' ? body.adminPassword : '';
            if (!adminPassword) {
                return res.status(400).json({
                    success: false,
                    code: 'ADMIN_PASSWORD_REQUIRED',
                    message:'An admin password is required to change the debt amount.'
                });
            }
            amountAuthorizer = await findAdminOnlyPasswordAuthorizer(readData(FILE_USERS), adminPassword);
            if (!amountAuthorizer) {
                return res.status(403).json({
                    success: false,
                    code: 'WRONG_ADMIN_PASSWORD',
                    message:'Incorrect admin password. The debt amount was not changed.'
                });
            }
        }
    }
    // Binasa ulit pagkatapos ng await (verification) para hindi ma-overwrite ang mga pagbabagong nangyari habang naghihintay.
    const debts = readData(FILE_DEBTS, []);
    const idx = debts.findIndex(d => d.id === req.params.id);
    if (idx === -1) return res.status(404).json({ success: false, message:'Debt record not found.' });
    let newDueAtIso;
    if (dueAt !== undefined) {
        if (!dueAt) {
            newDueAtIso = null;
        } else {
            const parsedDue = new Date(dueAt);
            if (isNaN(parsedDue.getTime())) {
                return res.status(400).json({ success: false, message:'The due date/time is not valid.' });
            }
            newDueAtIso = parsedDue.toISOString();
        }
    }
    if (customerName !== undefined && typeof customerName === 'string' && customerName.trim()) debts[idx].customerName = customerName.trim();
    if (phone !== undefined) debts[idx].phone = phone;
    if (note !== undefined) debts[idx].note = note;
    if (newDueAtIso !== undefined) debts[idx].dueAt = newDueAtIso;
    if (parsedNewAmount !== null) {
        const previousAmount = parseFloat(debts[idx].amount) || 0;
        debts[idx].amount = parsedNewAmount;
        if ((parseFloat(debts[idx].amountPaid) || 0) >= debts[idx].amount) {
            debts[idx].status ='paid';
            if (!debts[idx].paidAt) debts[idx].paidAt = new Date().toISOString();
            awardLoyaltyPointsForPaidDebt(debts[idx], req.authUser.username);
        } else if ((parseFloat(debts[idx].amountPaid) || 0) > 0) {
            debts[idx].status ='partial';
            debts[idx].paidAt = null;
        } else {
            debts[idx].status ='unpaid';
            debts[idx].paidAt = null;
        }
        if (Math.abs(previousAmount - parsedNewAmount) >= 0.005) {
            logAction(req.authUser.username, `Changed the debt amount of ${debts[idx].customerName} (Debt ID: ${debts[idx].id}) from ₱${previousAmount.toFixed(2)} to ₱${parsedNewAmount.toFixed(2)} (${isAdminUser ? 'by Admin' : `Authorized by Admin password (${amountAuthorizer ? amountAuthorizer.user.username : 'admin'})`})`);
        }
    }
    writeData(FILE_DEBTS, debts);
    res.json({ success: true, debt: debts[idx] });
});
app.post('/api/debts/:id/payment', requirePermission('customers'), requireFeature('customer_crm'), (req, res) => {
    const debts = readData(FILE_DEBTS, []);
    const idx = debts.findIndex(d => d.id === req.params.id);
    if (idx === -1) return res.status(404).json({ success: false, message:'Debt record not found.' });
    const paymentAmount = parseFloat(req.body.amount);
    if (!paymentAmount || paymentAmount <= 0) {
        return res.status(400).json({ success: false, message:'A valid payment amount is required.' });
    }
    const debt = debts[idx];
    const remainingBefore = Math.max(0, debt.amount - (debt.amountPaid || 0));
    if (paymentAmount > remainingBefore + 0.01) {
        return res.status(400).json({ success: false, message:`The payment (₱${paymentAmount.toFixed(2)}) exceeds the remaining balance (₱${remainingBefore.toFixed(2)}).` });
    }
    applyDebtPayment(debt, paymentAmount, req.authUser.username, { method: 'manual' });
    writeData(FILE_DEBTS, debts);
    logAction(req.authUser.username, `Recorded a payment for ${debt.customerName}'s debt: ₱${paymentAmount.toFixed(2)}`);
    res.json({ success: true, debt });
});
app.delete('/api/debts/:id', requirePermission('customers'), requireFeature('customer_crm'), rateLimit('debt-delete', 15, 10 * 60 * 1000), async (req, res) => {
    const { adminPassword } = req.body || {};
    if (!adminPassword) {
        return res.status(400).json({ success: false, message:'A password is required to delete a debt record.' });
    }
    const users = readData(FILE_USERS);
    const authResult = await findDebtDeleteAuthorizer(users, adminPassword);
    if (!authResult) {
        return res.status(403).json({
            success: false,
            code: 'WRONG_ADMIN_PASSWORD',
            message: 'Incorrect password. The debt record was not deleted.'
        });
    }
    let debts = readData(FILE_DEBTS, []);
    if (!debts.some(d => d.id === req.params.id)) {
        return res.status(404).json({ success: false, message:'Debt record not found.' });
    }
    debts = debts.filter(d => d.id !== req.params.id);
    writeData(FILE_DEBTS, debts);
    logAction(req.authUser.username, `Deleted debt record ID: ${req.params.id} (${authResult.isAdmin ? 'Authorized by Admin' : `Authorized via Own Password (${authResult.user.username}, RBAC)`})`);
    res.json({ success: true });
});
function buildDebtReceiptEmailHtml({ settings, debt, storeName }) {
    // Non-BIR mode: the word "Receipt" is reserved for official documents, so the debt statement is a "Debt Slip".
    const docName = isBirDocumentModeActive() ? 'Receipt' : 'Slip';
    const accent = resolveEmailAccentColor(settings);
    const storeAddress = settings.storeAddress || '';
    const storeContact = settings.storeContact || '';
    const footerText = settings.footerText || 'Thank you for your continued trust!';
    const amount = parseFloat(debt.amount) || 0;
    const paid = parseFloat(debt.amountPaid) || 0;
    const remaining = Math.max(0, amount - paid);
    const statusMeta = {
        paid: { label: 'FULLY PAID', bg: '#ecfdf5', fg: '#059669' },
        partial: { label: 'PARTIALLY PAID', bg: '#fffbeb', fg: '#b45309' },
        unpaid: { label: 'UNPAID', bg: '#fef2f2', fg: '#dc2626' }
    };
    const meta = statusMeta[debt.status] || statusMeta.unpaid;
    const paymentHistory = (Array.isArray(debt.paymentHistory) ? debt.paymentHistory.slice() : [])
        .sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0));
    const paymentRowsHtml = paymentHistory.length
        ? paymentHistory.map(p => `<tr>
            <td style="padding:7px 0;border-top:1px solid #f1f5f9;color:#64748b;">${p.date ? escapeHtml(new Date(p.date).toLocaleString()) : '—'}</td>
            <td align="right" style="padding:7px 0;border-top:1px solid #f1f5f9;color:#0f172a;font-weight:600;">₱${(parseFloat(p.amount) || 0).toFixed(2)}</td>
        </tr>`).join('')
        : `<tr><td colspan="2" style="padding:7px 0;color:#94a3b8;font-style:italic;">No payments recorded yet.</td></tr>`;
    const items = Array.isArray(debt.items) ? debt.items : [];
    const itemsHtml = items.length
        ? items.map(i => `<tr>
            <td style="padding:7px 0;border-top:1px solid #f1f5f9;color:#0f172a;">${escapeHtml(i.name)}</td>
            <td align="center" style="padding:7px 0;border-top:1px solid #f1f5f9;color:#64748b;">${escapeHtml(String(parseFloat(i.quantity) || 0))}</td>
            <td align="right" style="padding:7px 0;border-top:1px solid #f1f5f9;color:#0f172a;font-weight:600;">₱${(((parseFloat(i.price) || 0) * (parseFloat(i.quantity) || 0))).toFixed(2)}</td>
        </tr>`).join('')
        : `<tr><td colspan="3" style="padding:7px 0;color:#94a3b8;font-style:italic;">No linked products for this debt.</td></tr>`;
    const noteBlock = debt.note
        ? `<tr><td style="padding:16px 32px 0;">
            <div style="font-size:11px;color:#94a3b8;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">Note</div>
            <div style="background-color:#f8fafc;border-radius:10px;padding:12px 14px;font-size:13px;color:#334155;white-space:pre-wrap;">${escapeHtml(debt.note)}</div>
        </td></tr>`
        : '';
    const dueBlock = debt.dueAt
        ? `<tr><td style="padding:4px 0;">Due Date</td><td align="right" style="padding:4px 0;">${escapeHtml(new Date(debt.dueAt).toLocaleString())}</td></tr>`
        : `<tr><td style="padding:4px 0;">Due Date</td><td align="right" style="padding:4px 0;">No due date set</td></tr>`;
    const txRow = debt.transactionId
        ? `<tr><td style="padding:4px 0;">Linked Transaction</td><td align="right" style="padding:4px 0;">${escapeHtml(debt.transactionId)}</td></tr>`
        : '';
    return `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Debt ${docName} ${escapeHtml(debt.id)}</title>
</head>
<body style="margin:0;padding:0;background-color:#f1f5f9;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f1f5f9;padding:28px 12px;">
<tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 1px 4px rgba(15,23,42,0.08);">
    <tr><td style="background-color:${accent};padding:30px 32px;text-align:center;">
        <div style="color:#ffffff;font-size:22px;font-weight:800;letter-spacing:0.3px;">${escapeHtml(storeName)}</div>
        ${storeAddress ? `<div style="color:rgba(255,255,255,0.85);font-size:13px;margin-top:6px;">${escapeHtml(storeAddress)}</div>` : ''}
        ${storeContact ? `<div style="color:rgba(255,255,255,0.75);font-size:12px;margin-top:2px;">${escapeHtml(storeContact)}</div>` : ''}
        <div style="color:rgba(255,255,255,0.85);font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin-top:14px;">Digital Debt ${docName}</div>
    </td></tr>
    <tr><td style="padding:22px 32px 0;">
        <span style="display:inline-block;background-color:${meta.bg};color:${meta.fg};font-size:11px;font-weight:700;letter-spacing:0.4px;padding:6px 14px;border-radius:999px;">${meta.label}</span>
    </td></tr>
    <tr><td style="padding:18px 32px 0;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8fafc;border-radius:12px;">
            <tr><td style="padding:16px 18px;">
                <div style="font-size:11px;color:#64748b;text-transform:uppercase;letter-spacing:0.5px;">Remaining Balance</div>
                <div style="font-size:28px;font-weight:800;color:#0f172a;margin-top:2px;">₱${remaining.toFixed(2)}</div>
                <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:10px;font-size:12px;color:#64748b;">
                    <tr>
                        <td>Owed<br><b style="color:#0f172a;font-size:13px;">₱${amount.toFixed(2)}</b></td>
                        <td>Paid<br><b style="color:#0f172a;font-size:13px;">₱${paid.toFixed(2)}</b></td>
                    </tr>
                </table>
            </td></tr>
        </table>
    </td></tr>
    <tr><td style="padding:18px 32px 0;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;color:#64748b;">
            <tr><td style="padding:4px 0;">Customer</td><td align="right" style="padding:4px 0;font-weight:600;color:#0f172a;">${escapeHtml(debt.customerName || '')}</td></tr>
            ${debt.phone ? `<tr><td style="padding:4px 0;">Phone</td><td align="right" style="padding:4px 0;">${escapeHtml(debt.phone)}</td></tr>` : ''}
            ${dueBlock}
            ${txRow}
            <tr><td style="padding:4px 0;">${docName} No.</td><td align="right" style="padding:4px 0;">${escapeHtml(debt.id)}</td></tr>
        </table>
    </td></tr>
    <tr><td style="padding:20px 32px 0;"><div style="border-top:1px solid #e2e8f0;"></div></td></tr>
    <tr><td style="padding:16px 32px 0;">
        <div style="font-size:11px;color:#94a3b8;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">Payment Breakdown</div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;">
            ${paymentRowsHtml}
        </table>
    </td></tr>
    <tr><td style="padding:16px 32px 0;">
        <div style="font-size:11px;color:#94a3b8;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">Items Purchased</div>
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;">
            <tr>
                <td style="padding:0 0 8px;color:#94a3b8;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;">Item</td>
                <td align="center" style="padding:0 0 8px;color:#94a3b8;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;">Qty</td>
                <td align="right" style="padding:0 0 8px;color:#94a3b8;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;">Amount</td>
            </tr>
            ${itemsHtml}
        </table>
    </td></tr>
    ${noteBlock}
    <tr><td style="padding:28px 32px 6px;text-align:center;">
        <div style="font-size:14px;font-style:italic;color:#334155;">${escapeHtml(footerText)}</div>
    </td></tr>
    <tr><td style="padding:6px 32px 28px;text-align:center;">
        <div style="font-size:11px;color:#94a3b8;">This is an electronic ${docName.toLowerCase()}. Please keep this for your records.</div>
    </td></tr>
</table>
<div style="font-size:11px;color:#94a3b8;margin-top:16px;">Sent via ${escapeHtml(storeName)} · Powered by OmniPOS</div>
</td></tr>
</table>
</body>
</html>`;
}
app.post('/api/debts/:id/email-receipt', requirePermission('customers'), requireFeature('customer_crm'), rateLimit('debt-email-receipt', 20, 15 * 60 * 1000), async (req, res) => {
    const { toEmail } = req.body;
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!toEmail || !emailPattern.test(toEmail)) {
        return res.status(400).json({ success: false, message: 'Invalid email address.' });
    }
    const debts = readData(FILE_DEBTS, []);
    const debt = debts.find(d => d.id === req.params.id);
    if (!debt) {
        return res.status(404).json({ success: false, message: 'Debt record not found.' });
    }
    const rawReceiptSettings = readData(FILE_RECEIPT_SETTINGS, DEFAULT_RECEIPT_SETTINGS);
    const settings = getReceiptSettingsPublic(rawReceiptSettings);
    const mailCreds = getOtpMailCredentials(rawReceiptSettings);
    if (!mailCreds) {
        return res.status(400).json({
            success: false,
            message: 'No Sender Gmail configured yet. Set this up first under Users > Receipt Customization > OTP Sender Email.'
        });
    }
    try {
        const storeName = settings.storeName || 'OmniPOS';
        const debtDocName = isBirDocumentModeActive() ? 'Receipt' : 'Slip';
        const amount = parseFloat(debt.amount) || 0;
        const paid = parseFloat(debt.amountPaid) || 0;
        const remaining = Math.max(0, amount - paid);
        const statusLabels = { unpaid: 'Unpaid', partial: 'Partially Paid', paid: 'Fully Paid' };
        const paymentHistory = (Array.isArray(debt.paymentHistory) ? debt.paymentHistory.slice() : [])
            .sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0));
        const paymentLines = paymentHistory.length
            ? paymentHistory.map(p => `  ${p.date ? new Date(p.date).toLocaleString() : '—'} .......... ₱${(parseFloat(p.amount) || 0).toFixed(2)}`).join('\n')
            : '  No payments recorded yet.';
        const items = Array.isArray(debt.items) ? debt.items : [];
        const itemLines = items.length
            ? items.map(i => `  ${i.name} x${parseFloat(i.quantity) || 0} .......... ₱${(((parseFloat(i.price) || 0) * (parseFloat(i.quantity) || 0))).toFixed(2)}`).join('\n')
            : '  No linked products for this debt.';
        const textBody = `${storeName}\n${settings.storeAddress || ''}\n\nDIGITAL DEBT ${debtDocName.toUpperCase()}\nStatus: ${statusLabels[debt.status] || debt.status}\n\nCustomer: ${debt.customerName || ''}\n${debt.phone ? 'Phone: ' + debt.phone + '\n' : ''}Due: ${debt.dueAt ? new Date(debt.dueAt).toLocaleString() : 'No due date set'}\n${debt.transactionId ? 'Linked Transaction: ' + debt.transactionId + '\n' : ''}${debtDocName} No.: ${debt.id}\n\nAmount Owed: ₱${amount.toFixed(2)}\nAmount Paid: ₱${paid.toFixed(2)}\nRemaining Balance: ₱${remaining.toFixed(2)}\n\nPayment Breakdown:\n${paymentLines}\n\nItems Purchased:\n${itemLines}\n${debt.note ? '\nNote:\n  ' + debt.note + '\n' : ''}\n${settings.footerText || 'Thank you for your continued trust!'}`;
        const htmlBody = buildDebtReceiptEmailHtml({ settings, debt, storeName });
        const mailOptions = {
            from: `"${storeName}" <${mailCreds.user}>`,
            to: toEmail,
            subject: `Debt ${debtDocName} ${debt.id} - ${storeName}`,
            text: textBody,
            html: htmlBody
        };
        await sendMailSmart(mailCreds.user, mailCreds.pass, mailOptions);
        logAction(req.authUser ? req.authUser.username : 'Unknown', `Emailed debt e-${debtDocName.toLowerCase()} ${debt.id} to ${maskEmail(toEmail)}`);
        res.json({ success: true, message: `The e-${debtDocName.toLowerCase()} has been sent.` });
    } catch (err) {
        const mailErr = describeMailError(err);
        console.error(`Debt email receipt failed [${mailErr.code}]:`, err.message);
        res.status(mailErr.httpStatus).json({ success: false, errorCode: mailErr.code, retryable: mailErr.retryable, message: mailErr.message });
    }
});
app.post('/api/customers/:id/loyalty-card', requirePermission('loyalty_card_issue'), requireFeature('customer_crm'), rateLimit('loyalty-card-issue', 20, 10 * 60 * 1000), (req, res) => {
    const customers = readData(FILE_CUSTOMERS, []);
    const customer = customers.find(c => c.id === req.params.id);
    if (!customer) return res.status(404).json({ success: false, message:'Customer not found.' });
    const mode = (req.body && req.body.mode ==='static') ? 'static' : 'rotating';
    const wasReissue = !!(customer.loyaltyCard && !customer.loyaltyCard.revoked);
    const { token, card } = issueLoyaltyCard(customer, mode, req.authUser.username);
    writeData(FILE_CUSTOMERS, customers);
    logAction(req.authUser.username, `${wasReissue ? 'Regenerated' : 'Issued'} loyalty ${mode ==='static' ? 'card' : 'QR'} for customer: ${customer.name} (${customer.id})`);
    res.json({
        success: true,
        message: wasReissue
            ? 'Na-regenerate ang loyalty card/QR. Awtomatiko nang na-invalidate ang dating QR — ito na lang ang gagana.'
            : 'Naka-issue na ang bagong loyalty card/QR.',
        token,
        card: { cardId: card.cardId, mode: card.mode, issuedAt: card.issuedAt }
    });
});
app.post('/api/customers/:id/loyalty-card/revoke', requirePermission('loyalty_card_issue'), requireFeature('customer_crm'), (req, res) => {
    const customers = readData(FILE_CUSTOMERS, []);
    const customer = customers.find(c => c.id === req.params.id);
    if (!customer) return res.status(404).json({ success: false, message:'Customer not found.' });
    if (!customer.loyaltyCard) return res.status(400).json({ success: false, message:'Walang naka-issue na card/QR ang customer na ito.' });
    customer.loyaltyCard.revoked = true;
    writeData(FILE_CUSTOMERS, customers);
    logAction(req.authUser.username, `Revoked loyalty card/QR of customer: ${customer.name} (${customer.id})`);
    res.json({ success: true, message:'Na-revoke na ang loyalty card/QR na ito.' });
});
app.post('/api/customers/lookup-by-card', requirePermission('terminal'), rateLimit('loyalty-card-scan', 60, 10 * 60 * 1000), (req, res) => {
    const rawToken = req.body && req.body.token;
    if (!rawToken || typeof rawToken !=='string') {
        return res.status(400).json({ success: false, message:'Missing QR/card token.' });
    }
    const parts = rawToken.split('.');
    if (parts.length !== 4 || parts[0] !=='LC1') {
        return res.status(400).json({ success: false, message:'Hindi ito valid na Loyalty Card/QR.' });
    }
    const customers = readData(FILE_CUSTOMERS, []);
    const customer = customers.find(c => c.id === parts[1]);
    if (!customer) return res.status(404).json({ success: false, message:'Walang customer na nahanap para sa card/QR na ito.' });
    const check = verifyLoyaltyCardToken(customer, rawToken);
    if (!check.valid) return res.status(403).json({ success: false, code:'LOYALTY_CARD_INVALID', message: check.message });
    res.json({
        success: true,
        customer: { id: customer.id, name: customer.name, phone: customer.phone ||'', email: customer.email ||'', points: customer.points || 0 },
        cardMode: check.mode
    });
});
// AYOS/BUGFIX: Ang buong promocodes module ay wala talagang usage cap dati
// (walang maxUses/usedCount/per-customer limit) — kaya once gawa ang isang
// code, magagamit ito nang walang limitasyon habang buhay at "active" pa ito.
// Dinagdagan ito ng:
//   - maxUses / usedCount: pandaigdig (global) na limitasyon sa bilang ng
//     beses na magagamit ang isang code sa lahat ng benta.
//   - perCustomerLimit / redemptions{customerId: count}: opsyonal na
//     limitasyon kung ilang beses puwedeng gamitin ng IISANG customer.
// Ang paglago ng usedCount/redemptions ay nangyayari LAMANG sa loob ng
// processTransaction (sa ilalim ng transactionsMutexRunExclusive), kaya
// hindi ito madoble kahit magkasabay ang dalawang benta na gumagamit ng
// parehong code. Ang mga CRUD endpoint sa ibaba (create/edit/delete/reset)
// ay isinama rin ngayon sa parehong mutex dahil sumusulat din sila sa
// parehong FILE_PROMOCODES blob na ino-increment sa oras ng benta — kung
// hindi sila naka-mutex, posibleng ma-overwrite/mawala ang usedCount
// increment ng isang benta kapag sabay itong na-edit ng isang admin
// (parehong klase ng lost-update race gaya ng sa stock).
function evaluatePromoUsability(promo, { subtotal = null, customerId = null } = {}) {
    if (!promo) return { ok: false, message: 'Hindi valid ang promo code na ito.', code: 'PROMO_NOT_FOUND' };
    if (!promo.active) return { ok: false, message: 'Naka-disable na ang promo code na ito.', code: 'PROMO_INACTIVE' };
    if (promo.expiresAt && new Date(promo.expiresAt).getTime() < Date.now()) {
        return { ok: false, message: 'Na-expire na ang promo code na ito.', code: 'PROMO_EXPIRED' };
    }
    const maxUses = Math.max(0, parseInt(promo.maxUses, 10) || 0);
    const usedCount = Math.max(0, parseInt(promo.usedCount, 10) || 0);
    if (maxUses > 0 && usedCount >= maxUses) {
        return { ok: false, message: 'Naabot na ang maximum na bilang ng paggamit ng promo code na ito.', code: 'PROMO_LIMIT_REACHED' };
    }
    const perCustomerLimit = Math.max(0, parseInt(promo.perCustomerLimit, 10) || 0);
    if (perCustomerLimit > 0) {
        if (!customerId) {
            return { ok: false, message: 'Kailangan munang pumili ng customer — may per-customer na limitasyon ang promo code na ito.', code: 'PROMO_CUSTOMER_REQUIRED' };
        }
        const redemptions = (promo.redemptions && typeof promo.redemptions === 'object') ? promo.redemptions : {};
        const customerUses = Math.max(0, parseInt(redemptions[customerId], 10) || 0);
        if (customerUses >= perCustomerLimit) {
            return { ok: false, message: `Naabot na ng customer na ito ang limitasyon (${perCustomerLimit}x) sa promo code na ito.`, code: 'PROMO_CUSTOMER_LIMIT_REACHED' };
        }
    }
    if (subtotal !== null && promo.minSpend && subtotal < promo.minSpend) {
        return { ok: false, message: `Kailangan ng minimum na ₱${promo.minSpend.toFixed(2)} para magamit ang promo na ito.`, code: 'PROMO_MIN_SPEND' };
    }
    return { ok: true };
}
function promoRemainingUses(promo) {
    const maxUses = Math.max(0, parseInt(promo && promo.maxUses, 10) || 0);
    if (maxUses <= 0) return null;
    const usedCount = Math.max(0, parseInt(promo && promo.usedCount, 10) || 0);
    return Math.max(0, maxUses - usedCount);
}
app.get('/api/promocodes', requirePermission('products'), requireFeature('promo_codes'), (req, res) => {
    const promos = readData(FILE_PROMOCODES, []).map(p => ({ ...p, remainingUses: promoRemainingUses(p) }));
    res.json(promos);
});
app.post('/api/promocodes', requirePermission('products'), requireFeature('promo_codes'), async (req, res) => {
    await transactionsMutexRunExclusive(() => processCreatePromoCode(req, res));
});
function processCreatePromoCode(req, res) {
    let { code, type, value, description, expiresAt, minSpend, maxUses, perCustomerLimit } = req.body;
    code = (code ||'').trim().toUpperCase();
    if (!code) return res.status(400).json({ success: false, message:'Kailangan ng promo code.' });
    if (!['percent','fixed'].includes(type)) return res.status(400).json({ success: false, message:'Invalid discount type (percent o fixed lang).' });
    value = parseFloat(value);
    if (isNaN(value) || value <= 0) return res.status(400).json({ success: false, message:'Invalid discount value.' });
    if (type ==='percent' && value > 100) return res.status(400).json({ success: false, message:'Hindi pwedeng lumagpas sa 100% ang percent discount.' });
    const maxUsesNum = maxUses === undefined || maxUses === null || maxUses === '' ? 0 : parseInt(maxUses, 10);
    if (isNaN(maxUsesNum) || maxUsesNum < 0) {
        return res.status(400).json({ success: false, message:'Invalid ang Max Uses — dapat 0 (walang limit) o positibong buong numero.' });
    }
    const perCustomerLimitNum = perCustomerLimit === undefined || perCustomerLimit === null || perCustomerLimit === '' ? 0 : parseInt(perCustomerLimit, 10);
    if (isNaN(perCustomerLimitNum) || perCustomerLimitNum < 0) {
        return res.status(400).json({ success: false, message:'Invalid ang Per-Customer Limit — dapat 0 (walang limit) o positibong buong numero.' });
    }
    const promos = readData(FILE_PROMOCODES, []);
    if (promos.some(p => p.code === code)) {
        return res.status(400).json({ success: false, message:'Existing na ang promo code na ito.' });
    }
    const promo = {
        code, type, value,
        description: description ||'',
        active: true,
        expiresAt: expiresAt || null,
        minSpend: parseFloat(minSpend) || 0,
        maxUses: maxUsesNum,
        usedCount: 0,
        perCustomerLimit: perCustomerLimitNum,
        redemptions: {},
        createdAt: new Date().toISOString(),
        createdBy: req.authUser.username
    };
    promos.unshift(promo);
    writeData(FILE_PROMOCODES, promos);
    logAction(req.authUser.username, `Added promo code: ${code}` + (maxUsesNum > 0 ? ` (max uses: ${maxUsesNum})` : '') + (perCustomerLimitNum > 0 ? ` (per-customer limit: ${perCustomerLimitNum})` : ''));
    res.json({ success: true, promo: { ...promo, remainingUses: promoRemainingUses(promo) } });
}
app.put('/api/promocodes/:code', requirePermission('products'), requireFeature('promo_codes'), async (req, res) => {
    await transactionsMutexRunExclusive(() => processUpdatePromoCode(req, res));
});
function processUpdatePromoCode(req, res) {
    const codeParam = req.params.code.toUpperCase();
    const promos = readData(FILE_PROMOCODES, []);
    const idx = promos.findIndex(p => p.code === codeParam);
    if (idx === -1) return res.status(404).json({ success: false, message:'Promo code not found.' });
    const { type, value, description, active, expiresAt, minSpend, maxUses, perCustomerLimit } = req.body;
    if (type !== undefined) promos[idx].type = type;
    if (value !== undefined) promos[idx].value = parseFloat(value);
    if (description !== undefined) promos[idx].description = description;
    if (active !== undefined) promos[idx].active = !!active;
    if (expiresAt !== undefined) promos[idx].expiresAt = expiresAt;
    if (minSpend !== undefined) promos[idx].minSpend = parseFloat(minSpend) || 0;
    if (maxUses !== undefined) {
        const maxUsesNum = maxUses === null || maxUses === '' ? 0 : parseInt(maxUses, 10);
        if (isNaN(maxUsesNum) || maxUsesNum < 0) {
            return res.status(400).json({ success: false, message:'Invalid ang Max Uses — dapat 0 (walang limit) o positibong buong numero.' });
        }
        promos[idx].maxUses = maxUsesNum;
    }
    if (perCustomerLimit !== undefined) {
        const perCustomerLimitNum = perCustomerLimit === null || perCustomerLimit === '' ? 0 : parseInt(perCustomerLimit, 10);
        if (isNaN(perCustomerLimitNum) || perCustomerLimitNum < 0) {
            return res.status(400).json({ success: false, message:'Invalid ang Per-Customer Limit — dapat 0 (walang limit) o positibong buong numero.' });
        }
        promos[idx].perCustomerLimit = perCustomerLimitNum;
    }
    if (!promos[idx].redemptions || typeof promos[idx].redemptions !== 'object') promos[idx].redemptions = {};
    if (typeof promos[idx].usedCount !== 'number') promos[idx].usedCount = 0;
    writeData(FILE_PROMOCODES, promos);
    logAction(req.authUser.username, `Updated promo code: ${codeParam}`);
    res.json({ success: true, promo: { ...promos[idx], remainingUses: promoRemainingUses(promos[idx]) } });
}
app.post('/api/promocodes/:code/reset-usage', requirePermission('products'), requireFeature('promo_codes'), async (req, res) => {
    await transactionsMutexRunExclusive(() => processResetPromoUsage(req, res));
});
function processResetPromoUsage(req, res) {
    const codeParam = req.params.code.toUpperCase();
    const promos = readData(FILE_PROMOCODES, []);
    const idx = promos.findIndex(p => p.code === codeParam);
    if (idx === -1) return res.status(404).json({ success: false, message:'Promo code not found.' });
    const previousUsedCount = Math.max(0, parseInt(promos[idx].usedCount, 10) || 0);
    promos[idx].usedCount = 0;
    promos[idx].redemptions = {};
    writeData(FILE_PROMOCODES, promos);
    logAction(req.authUser.username, `Reset usage counter ng promo code: ${codeParam} (dating usedCount: ${previousUsedCount})`);
    res.json({ success: true, promo: { ...promos[idx], remainingUses: promoRemainingUses(promos[idx]) } });
}
app.delete('/api/promocodes/:code', requirePermission('products'), requireFeature('promo_codes'), async (req, res) => {
    await transactionsMutexRunExclusive(() => processDeletePromoCode(req, res));
});
function processDeletePromoCode(req, res) {
    const codeParam = req.params.code.toUpperCase();
    let promos = readData(FILE_PROMOCODES, []);
    if (!promos.some(p => p.code === codeParam)) {
        return res.status(404).json({ success: false, message:'Promo code not found.' });
    }
    promos = promos.filter(p => p.code !== codeParam);
    writeData(FILE_PROMOCODES, promos);
    logAction(req.authUser.username, `Deleted promo code: ${codeParam}`);
    res.json({ success: true });
}
app.get('/api/promocodes/:code/validate', requireFeature('promo_codes'), (req, res) => {
    const codeParam = req.params.code.toUpperCase();
    const subtotal = parseFloat(req.query.subtotal) || 0;
    const customerId = req.query.customerId ? String(req.query.customerId) : null;
    const promos = readData(FILE_PROMOCODES, []);
    const promo = promos.find(p => p.code === codeParam);
    const usability = evaluatePromoUsability(promo, { subtotal, customerId });
    if (!usability.ok) return res.json({ success: false, message: usability.message, code: usability.code });
    let discountAmount = promo.type ==='percent' ? (subtotal * promo.value / 100) : promo.value;
    discountAmount = Math.min(Math.max(discountAmount, 0), subtotal);
    res.json({
        success: true,
        promo: { ...promo, remainingUses: promoRemainingUses(promo) },
        discountAmount: Math.round(discountAmount * 100) / 100
    });
});
function computeShiftSummary(periodStartIso, periodEndIso, cashierFilter) {
    const start = new Date(periodStartIso).getTime();
    const end = new Date(periodEndIso).getTime();
    // SCALE FIX: SQL na ang nagtatapon ng mga benta na malinaw na wala sa panahon ng shift (superset lang ito; ang
    // eksaktong dating filter sa ibaba ang nagpapasya pa rin). Kung hindi mahulaan ang window, buong basa gaya ng dati.
    const allTx = readRowsInIsoWindow(FILE_TRANSACTIONS, 'isoDate', start, end) || readData(FILE_TRANSACTIONS);
    const cashierKey = cashierFilter ? String(cashierFilter).toLowerCase() : null;
    const txs = allTx.filter(t => {
        const ts = new Date(t.isoDate || t.timestamp || 0).getTime();
        if (isNaN(ts) || ts <= start || ts > end) return false;
        if (cashierKey && (t.cashier ||'').toLowerCase() !== cashierKey) return false;
        return true;
    });
    const paymentBreakdown = {};
    let grossSales = 0, totalDiscount = 0, netSales = 0;
    txs.forEach(t => {
        const disc = parseFloat(t.discount || 0) || 0;
        const refundedForTx = Math.min(parseFloat(t.total || 0) || 0, parseFloat(t.totalRefunded || 0) || 0);
        const net = Math.max(0, (parseFloat(t.total || 0) || 0) - refundedForTx);
        totalDiscount += disc;
        netSales += net;
        grossSales += net + disc;
        if (Array.isArray(t.payments) && t.payments.length > 0) {
            // BUGFIX: the tendered amounts of a split payment include the change handed back, and that change always
            // comes out of the cash drawer. Splitting the net sale in proportion to the TENDERED amounts overstated CASH
            // (e.g. GCash 300 + Cash 500 for a 700 sale gave Cash 437.50 instead of 400), so Expected Cash was too high
            // and every Z-Reading showed a false shortage. The change is now taken off the CASH line(s) first.
            const payLines = t.payments.map(p => ({
                method: (p.method || 'CASH').toString().toUpperCase(),
                amount: Math.max(0, parseFloat(p.amount) || 0)
            }));
            const tenderedSum = payLines.reduce((s, l) => s + l.amount, 0);
            let changeLeft = Math.max(0, Math.round((tenderedSum - (parseFloat(t.total) || 0)) * 100) / 100);
            payLines.forEach(l => {
                if (changeLeft <= 0 || l.method !== 'CASH') return;
                const take = Math.min(l.amount, changeLeft);
                l.amount = Math.round((l.amount - take) * 100) / 100;
                changeLeft = Math.round((changeLeft - take) * 100) / 100;
            });
            if (changeLeft > 0.004) {
                // More change than cash tendered (should not happen): spread the remainder proportionally.
                const restSum = payLines.reduce((s, l) => s + l.amount, 0);
                if (restSum > 0) payLines.forEach(l => { l.amount = Math.max(0, l.amount - changeLeft * (l.amount / restSum)); });
            }
            const appliedSum = payLines.reduce((s, l) => s + l.amount, 0);
            payLines.forEach(l => {
                const method = l.method;
                // Shares always add up to this transaction's net (refunds are taken out proportionally).
                const share = appliedSum > 0
                    ? Math.round((net * (l.amount / appliedSum)) * 100) / 100
                    : Math.round((net / payLines.length) * 100) / 100;
                if (!paymentBreakdown[method]) paymentBreakdown[method] = { count: 0, total: 0 };
                paymentBreakdown[method].total = Math.round((paymentBreakdown[method].total + share) * 100) / 100;
            });
            const primaryMethod = payLines[0].method;
            paymentBreakdown[primaryMethod].count += 1;
        } else {
            const method = (t.payment_method || t.method ||'CASH').toUpperCase();
            if (!paymentBreakdown[method]) paymentBreakdown[method] = { count: 0, total: 0 };
            paymentBreakdown[method].count += 1;
            paymentBreakdown[method].total = Math.round((paymentBreakdown[method].total + net) * 100) / 100;
        }
    });
    // SCALE FIX: user logs na nasa pagitan lang ng start at end ang binabasa (superset; eksaktong filter pa rin sa ibaba).
    const logs = readRowsInNumberWindow(FILE_USERLOGS, 'id', start, end) || readData(FILE_USERLOGS);
    const voidLogs = logs.filter(l => l.action && l.action.indexOf('VOIDED Transaction') === 0 && l.id > start && l.id <= end
        && (!cashierKey || (l.username ||'').toLowerCase() === cashierKey));
    const voidCount = voidLogs.length;
    const voidedAmount = Math.round(voidLogs.reduce((sum, l) => sum + (parseFloat(l.voidedAmount) || 0), 0) * 100) / 100;
    const refundLogs = logs.filter(l => l.action && l.action.indexOf('REFUNDED') === 0 && l.id > start && l.id <= end
        && (!cashierKey || (l.username ||'').toLowerCase() === cashierKey));
    const refundCount = refundLogs.length;
    const refundedAmount = Math.round(refundLogs.reduce((sum, l) => sum + (parseFloat(l.refundedAmount) || 0), 0) * 100) / 100;
    return {
        periodStart: new Date(start).toISOString(),
        periodEnd: new Date(end).toISOString(),
        transactionCount: txs.length,
        grossSales: Math.round(grossSales * 100) / 100,
        totalDiscount: Math.round(totalDiscount * 100) / 100,
        netSales: Math.round(netSales * 100) / 100,
        paymentBreakdown,
        voidCount,
        voidedAmount,
        refundCount,
        refundedAmount
    };
}
function readShiftMetaStore() {
    const raw = readData(FILE_SHIFT_META, {});
    if (raw && !raw.cashiers && (raw.beginningCash !== undefined || raw.lastCloseAt !== undefined)) {
        return { cashiers: {}, legacyLastCloseAt: raw.lastCloseAt || null };
    }
    if (!raw.cashiers) raw.cashiers = {};
    return raw;
}
function writeShiftMetaStore(store) {
    writeData(FILE_SHIFT_META, store);
}
function getCashierShiftMeta(store, username) {
    const existingKey = Object.keys(store.cashiers).find(k => k.toLowerCase() === (username ||'').toLowerCase());
    if (existingKey) return store.cashiers[existingKey];
    store.cashiers[username] = { lastCloseAt: store.legacyLastCloseAt || null };
    return store.cashiers[username];
}
app.get('/api/shift/current', (req, res) => {
    const role = req.authUser && req.authUser.role;
    const isAdminRole = (role ||'').toLowerCase() ==='admin';
    const canControlOthers = isAdminRole || !!getPermissionsForRole(role).shift_close_control;
    const requestedCashier = (req.query.cashier ||'').toString().trim();
    let targetCashier = req.authUser.username;
    if (requestedCashier && requestedCashier.toLowerCase() !== targetCashier.toLowerCase()) {
        if (!canControlOthers) {
            return res.status(403).json({ success: false, message:'Akses Denied: Wala kang pahintulot na tingnan/kontrolin ang shift ng ibang cashier.' });
        }
        targetCashier = requestedCashier;
    }
    const store = readShiftMetaStore();
    const targetHasOpenShift = (() => {
        const m = getCashierShiftMeta(store, targetCashier);
        return m.beginningCash !== undefined && m.beginningCash !== null;
    })();
    if (!targetHasOpenShift) {
        const gateResult = checkShiftManagementUnlocked();
        if (!gateResult.unlocked) return res.status(402).json(gateResult.body);
    }
    const meta = getCashierShiftMeta(store, targetCashier);
    const periodStart = meta.lastCloseAt || new Date(0).toISOString();
    const summary = computeShiftSummary(periodStart, new Date().toISOString(), targetCashier);
    const canViewAmounts = isAdminRole || !!getPermissionsForRole(role).shiftreport_view_amounts;
    if (!canViewAmounts) {
        delete summary.grossSales;
        delete summary.totalDiscount;
        delete summary.netSales;
        delete summary.voidedAmount;
        delete summary.refundedAmount;
        delete summary.paymentBreakdown;
    }
    res.json({
        success: true,
        summary,
        cashier: targetCashier,
        viewingOtherCashier: targetCashier.toLowerCase() !== req.authUser.username.toLowerCase(),
        canControlOtherShifts: canControlOthers,
        beginningCash: (meta.beginningCash !== undefined && meta.beginningCash !== null) ? meta.beginningCash : null,
        beginningCashLocked: meta.beginningCash !== undefined && meta.beginningCash !== null,
        beginningCashSetBy: meta.beginningCashSetBy || null
    });
});
app.get('/api/shift/xreading', (req, res) => {
    // X-Reading: a read-only, printable snapshot of the CURRENT (still-open) shift's running
    // totals. Unlike Z-Reading (/api/shift/close), this does NOT close the shift, does NOT
    // reset lastCloseAt, and can be generated as many times as needed during the day — the
    // standard "mid-shift reading" cashiers/supervisors expect from a Philippine retail POS.
    const role = req.authUser && req.authUser.role;
    const isAdminRole = (role || '').toLowerCase() === 'admin';
    const canControlOthers = isAdminRole || !!getPermissionsForRole(role).shift_close_control;
    const requestedCashier = (req.query.cashier || '').toString().trim();
    let targetCashier = req.authUser.username;
    if (requestedCashier && requestedCashier.toLowerCase() !== targetCashier.toLowerCase()) {
        if (!canControlOthers) {
            return res.status(403).json({ success: false, message: 'Access Denied: You do not have permission to view another cashier\'s shift.' });
        }
        targetCashier = requestedCashier;
    }
    const store = readShiftMetaStore();
    const meta = getCashierShiftMeta(store, targetCashier);
    const targetHasOpenShift = meta.beginningCash !== undefined && meta.beginningCash !== null;
    if (!targetHasOpenShift) {
        const gateResult = checkShiftManagementUnlocked();
        if (!gateResult.unlocked) return res.status(402).json(gateResult.body);
    }
    const periodStart = meta.lastCloseAt || new Date(0).toISOString();
    const periodEnd = new Date().toISOString();
    const summary = computeShiftSummary(periodStart, periodEnd, targetCashier);
    const canViewAmounts = isAdminRole || !!getPermissionsForRole(role).shiftreport_view_amounts;
    const beginningCash = (meta.beginningCash !== undefined && meta.beginningCash !== null) ? meta.beginningCash : null;
    let expectedCash = null;
    if (canViewAmounts && beginningCash !== null) {
        const cashSales = (summary.paymentBreakdown['CASH'] && summary.paymentBreakdown['CASH'].total) || 0;
        expectedCash = Math.round((beginningCash + cashSales) * 100) / 100;
    }
    if (!canViewAmounts) {
        delete summary.grossSales;
        delete summary.totalDiscount;
        delete summary.netSales;
        delete summary.voidedAmount;
        delete summary.refundedAmount;
        delete summary.paymentBreakdown;
    }
    const record = {
        id: 'X-' + Date.now(),
        generatedBy: req.authUser.username,
        cashier: targetCashier,
        generatedOnBehalf: targetCashier.toLowerCase() !== req.authUser.username.toLowerCase(),
        generatedAt: periodEnd,
        beginningCash,
        expectedCash,
        ...summary
    };
    logAction(req.authUser.username, `Generated X-Reading ${record.id} for '${targetCashier}' (running totals — shift stays OPEN): ${summary.transactionCount} tx${canViewAmounts && summary.netSales !== undefined ? `, Net Sales ₱${summary.netSales}` : ''}`);
    res.json({ success: true, xreading: record });
});
app.get('/api/shift/open-list', (req, res) => {
    const role = req.authUser && req.authUser.role;
    const isAdminRole = (role ||'').toLowerCase() ==='admin';
    const canControlOthers = isAdminRole || !!getPermissionsForRole(role).shift_close_control;
    if (!canControlOthers) {
        return res.status(403).json({ success: false, message:'Akses Denied: Wala kang pahintulot na kontrolin ang shift close ng ibang cashier.' });
    }
    const store = readShiftMetaStore();
    const openShifts = Object.keys(store.cashiers)
        .map(username => ({ username, meta: store.cashiers[username] }))
        .filter(c => c.meta && c.meta.beginningCash !== undefined && c.meta.beginningCash !== null)
        .map(c => ({
            username: c.username,
            beginningCash: c.meta.beginningCash,
            beginningCashSetAt: c.meta.beginningCashSetAt || null
        }));
    res.json({ success: true, openShifts });
});
app.post('/api/shift/open-cash', requirePermission('terminal'), requireFeature('shift_management'), rateLimit('shift-open-cash', 20, 10 * 60 * 1000), (req, res) => {
    const store = readShiftMetaStore();
    const meta = getCashierShiftMeta(store, req.authUser.username);
    if (meta.beginningCash !== undefined && meta.beginningCash !== null) {
        return res.status(409).json({
            success: false,
            message:'The Beginning Cash for your current shift has already been set and locked.',
            beginningCash: meta.beginningCash
        });
    }
    const amount = parseFloat(req.body.beginningCash);
    if (isNaN(amount) || amount < 0) {
        return res.status(400).json({ success: false, message:'Invalid Beginning Cash amount.' });
    }
    meta.beginningCash = Math.round(amount * 100) / 100;
    meta.beginningCashSetBy = req.authUser.username;
    meta.beginningCashSetAt = new Date().toISOString();
    writeShiftMetaStore(store);
    logAction(req.authUser.username, `Set the Beginning Cash Float for a new shift: ₱${meta.beginningCash.toFixed(2)}`);
    res.json({ success: true, beginningCash: meta.beginningCash });
});
app.post('/api/shift/close', rateLimit('shift-close', 20, 10 * 60 * 1000), async (req, res) => {
    const role = req.authUser && req.authUser.role;
    const isAdminRole = (role ||'').toLowerCase() ==='admin';
    const canControlOthers = isAdminRole || !!getPermissionsForRole(role).shift_close_control;
    const { adminPassword } = req.body;
    if (!adminPassword) {
        return res.status(400).json({ success: false, message:'Kailangan ng Admin/Manager/Supervisor password para isara ang shift / Z-Reading.' });
    }
    const usersForShiftClose = readData(FILE_USERS);
    const shiftCloseAuth = await findShiftCloseAuthorizer(usersForShiftClose, adminPassword);
    if (!shiftCloseAuth) {
        return res.status(403).json({
            success: false,
            code:'WRONG_ADMIN_PASSWORD',
            message:'Maling password. Hindi pinahintulutan ang pag-close ng shift / Z-Reading.'
        });
    }
    const requestedTarget = (req.body.targetCashier ||'').toString().trim();
    let targetCashier = req.authUser.username;
    let closedOnBehalf = false;
    if (requestedTarget && requestedTarget.toLowerCase() !== targetCashier.toLowerCase()) {
        if (!canControlOthers) {
            return res.status(403).json({ success: false, message:'Akses Denied: Wala kang pahintulot na isara ang shift ng ibang cashier. Kailangan ng Admin/Supervisor control (shift_close_control) para dito.' });
        }
        targetCashier = requestedTarget;
        closedOnBehalf = true;
    }
    const store = readShiftMetaStore();
    const meta = getCashierShiftMeta(store, targetCashier);
    const targetHasOpenShift = meta.beginningCash !== undefined && meta.beginningCash !== null;
    if (!targetHasOpenShift) {
        const gateResult = checkShiftManagementUnlocked();
        if (!gateResult.unlocked) return res.status(402).json(gateResult.body);
    }
    const beginningCash = (meta.beginningCash !== undefined && meta.beginningCash !== null)
        ? meta.beginningCash
        : req.body.beginningCash;
    const { endingCashCounted, notes } = req.body;
    const periodStart = meta.lastCloseAt || new Date(0).toISOString();
    const periodEnd = new Date().toISOString();
    const summary = computeShiftSummary(periodStart, periodEnd, targetCashier);
    const isZeroActivityClose = summary.transactionCount === 0 && summary.voidCount === 0 && summary.refundCount === 0;
    if (isZeroActivityClose && !targetHasOpenShift) {
        return res.json({ success: false, message: `Walang bukas na shift at walang bagong transaksyon o void para kay ${closedOnBehalf ? targetCashier :'sa iyo'}. Wala pang kailangang i-close.` });
    }
    const shifts = readData(FILE_SHIFTS, []);
    const cashSales = (summary.paymentBreakdown['CASH'] && summary.paymentBreakdown['CASH'].total) || 0;
    const beginCashNum = parseFloat(beginningCash) || 0;
    const expectedCash = Math.round((beginCashNum + cashSales) * 100) / 100;
    const hasCount = endingCashCounted !== undefined && endingCashCounted !=='' && endingCashCounted !== null;
    const endCashNum = hasCount ? (parseFloat(endingCashCounted) || 0) : null;
    const cashVariance = hasCount ? Math.round((endCashNum - expectedCash) * 100) / 100 : null;
    const record = {
        id:'Z-' + Date.now(),
        closedBy: targetCashier,
        closedOnBehalfBy: closedOnBehalf ? req.authUser.username : null,
        beginningCash: beginCashNum,
        endingCashCounted: endCashNum,
        cashSales,
        expectedCash,
        cashVariance,
        notes: notes ||'',
        noSalesShift: isZeroActivityClose,
        ...summary
    };
    shifts.unshift(record);
    writeData(FILE_SHIFTS, shifts);
    store.cashiers[targetCashier] = { lastCloseAt: periodEnd };
    writeShiftMetaStore(store);
    const varianceLog = cashVariance === null
        ?''
        : (cashVariance < 0
            ? `, Cash SHORT ₱${Math.abs(cashVariance).toFixed(2)}`
            : (cashVariance > 0 ? `, Cash OVER ₱${cashVariance.toFixed(2)}` :', Cash Exact'));
    const noSalesLog = isZeroActivityClose ?' (Walang Transaksyon - Shift Handover Lang)' :'';
    const authorizedByLog = shiftCloseAuth.isAdmin
        ?'Authorized by Admin'
        : `Authorized via Own Password (${shiftCloseAuth.user.username}, RBAC)`;
    const actionLog = closedOnBehalf
        ? `Closed shift / Z-Reading ${record.id} ng cashier '${targetCashier}' (Admin/Supervisor Control): ${summary.transactionCount} tx, Net Sales ₱${summary.netSales}${varianceLog}${noSalesLog} — ${authorizedByLog}`
        : `Closed shift / Z-Reading ${record.id}: ${summary.transactionCount} tx, Net Sales ₱${summary.netSales}${varianceLog}${noSalesLog} — ${authorizedByLog}`;
    logAction(req.authUser.username, actionLog);
    res.json({ success: true, shift: record });
});
app.get('/api/shifts', requirePermission('shiftreport'), requireFeature('shift_management'), (req, res) => {
    const allShifts = readData(FILE_SHIFTS, []);
    const requester = req.authUser && req.authUser.username;
    const activeRole = req.authUser && req.authUser.role;
    const isAdminRole = (activeRole ||'').toLowerCase() ==='admin';
    const canViewAll = isAdminRole || !!getPermissionsForRole(activeRole).shiftreport_view_all;
    const scopedShifts = canViewAll
        ? allShifts
        : allShifts.filter(s => (s.closedBy ||'').toLowerCase() === (requester ||'').toLowerCase());
    const hasLimit = req.query.limit !== undefined && req.query.limit !== null && req.query.limit !=='';
    if (!hasLimit) {
        return res.json(scopedShifts);
    }
    const limit = Math.max(1, Math.min(200, parseInt(req.query.limit, 10) || 25));
    const offset = Math.max(0, parseInt(req.query.offset, 10) || 0);
    const page = scopedShifts.slice(offset, offset + limit);
    res.json({
        shifts: page,
        total: scopedShifts.length,
        offset,
        limit,
        hasMore: offset + page.length < scopedShifts.length
    });
});
